import React, { useState, useRef } from 'react';
import { useDropzone } from 'react-dropzone';
import { Upload, FileText, CheckCircle2, Target, BookOpen, Mail, Sparkles, Cpu, ArrowRight, Zap } from 'lucide-react';
import { useAnalyze } from '../hooks/useAnalyze';
import LoadingScreen from '../components/LoadingScreen';
import BackgroundEffects from '../components/BackgroundEffects';
import AiAgentsBar from '../components/AiAgentsBar';
import SharedProfilesExplorer from '../components/SharedProfilesExplorer';
import CinematicStory from '../components/CinematicStory';
import { useNavigate } from 'react-router-dom';

const Home = () => {
  const [file, setFile] = useState(null);
  const [jobDescription, setJobDescription] = useState('');
  const [showExplorer, setShowExplorer] = useState(false);

  const commandCenterRef = useRef(null);
  const { analyze, loading, progress, currentStep } = useAnalyze();
  const navigate = useNavigate();

  const onDrop = (acceptedFiles) => {
    if (acceptedFiles.length > 0) {
      setFile(acceptedFiles[0]);
    }
  };

  const { getRootProps, getInputProps, isDragActive } = useDropzone({
    onDrop,
    accept: {
      'application/pdf': ['.pdf'],
      'application/vnd.openxmlformats-officedocument.wordprocessingml.document': ['.docx']
    },
    maxFiles: 1
  });

  const scrollToCommandCenter = () => {
    if (commandCenterRef.current) {
      commandCenterRef.current.scrollIntoView({ behavior: 'smooth' });
    }
  };

  const handleAnalyze = () => {
    console.log('[DEBUG Home.js] "Analyze Resume & Verify Profile" button clicked!');
    if (!file) {
      console.warn('[DEBUG Home.js] Validation failed: No file uploaded.');
      alert('Please upload a resume (PDF or DOCX)');
      return;
    }

    if (!jobDescription.trim()) {
      console.warn('[DEBUG Home.js] Validation failed: Job description empty.');
      alert('Please enter a job description');
      return;
    }

    console.log('[DEBUG Home.js] Validation passed. Calling analyze() hook...');
    analyze(file, jobDescription);
  };

  const handleSelectMockProfile = (mockAnalysis) => {
    sessionStorage.setItem('analysisResult', JSON.stringify(mockAnalysis));
    navigate('/results');
  };

  if (loading) {
    return (
      <LoadingScreen
        progress={progress}
        currentStep={currentStep}
      />
    );
  }

  return (
    <div className="min-h-screen bg-scifi-900 text-scifi-100 relative overflow-hidden">
      {/* Dynamic Animated Background */}
      <BackgroundEffects />

      {/* 1. Cinematic Story Sequence (Sections 1-6 with Gemini Custom Artwork) */}
      <CinematicStory onEnterCommandCenter={scrollToCommandCenter} />

      {/* 2. Main Input Command Center */}
      <div ref={commandCenterRef} className="max-w-6xl mx-auto px-4 pt-16 pb-16 relative z-10">

        {/* Command Center Title */}
        <div className="text-center mb-10">
          <div className="inline-flex items-center space-x-2 px-4 py-2 rounded-full glass-pill border border-scifi-600/40 text-xs font-mono mb-4 shadow-purple-glow">
            <Sparkles className="w-4 h-4 text-scifi-200 animate-spin-slow" />
            <span className="text-scifi-100 font-semibold tracking-wide">
              SkillBridge AI v2.0 Command Center
            </span>
          </div>

          <h2 className="text-3xl sm:text-5xl font-heading font-extrabold text-scifi-100 tracking-tight">
            Developer Intelligence Core
          </h2>
          <p className="text-scifi-200 text-sm font-mono mt-2">
            Upload your resume or inspect pre-configured shared developer profiles
          </p>
        </div>

        {/* AI Agents Status Grid */}
        <AiAgentsBar />

        <div className="grid md:grid-cols-2 gap-8 my-8">

          {/* Futuristic Resume Upload Dropzone */}
          <div className="glass-card p-6 sm:p-8 rounded-3xl border border-scifi-600/30 shadow-2xl relative overflow-hidden group">

            {/* Scan Beam Effect */}
            <div className="absolute inset-0 bg-scanline-purple pointer-events-none opacity-40" />

            <h2 className="text-xl font-heading font-bold mb-4 flex items-center text-scifi-100">
              <Upload className="w-5 h-5 mr-3 text-scifi-200" />
              1. Upload Developer Resume
            </h2>

            <div
              {...getRootProps()}
              className={`relative border-2 border-dashed rounded-2xl p-8 text-center cursor-pointer transition-all duration-300 overflow-hidden ${
                isDragActive
                  ? 'border-scifi-400 bg-scifi-600/20 shadow-purple-glow scale-[1.01]'
                  : 'border-scifi-600/30 bg-scifi-950/60 hover:border-scifi-600/60 hover:bg-scifi-900/60'
              }`}
            >
              <input {...getInputProps()} />

              {file ? (
                <div className="flex flex-col items-center justify-center space-y-3 py-4">
                  <div className="p-4 rounded-2xl bg-scifi-600/20 border border-scifi-600/50 text-scifi-100 shadow-purple-glow">
                    <FileText className="w-10 h-10" />
                  </div>
                  <div>
                    <p className="font-heading font-bold text-scifi-100 text-base">{file.name}</p>
                    <p className="text-xs font-mono text-scifi-200 mt-1">
                      {(file.size / 1024).toFixed(1)} KB • Ready for Parsing
                    </p>
                  </div>
                  <span className="px-3 py-1 rounded-full text-xs font-mono bg-scifi-600/30 text-scifi-100 border border-scifi-600/50">
                    ✓ File Validated
                  </span>
                </div>
              ) : (
                <div className="py-6 space-y-4">
                  <div className="w-16 h-16 rounded-2xl bg-scifi-600/20 border border-scifi-600/40 flex items-center justify-center mx-auto text-scifi-200 group-hover:scale-110 transition-transform">
                    <Upload className="w-8 h-8" />
                  </div>

                  <div>
                    <p className="text-scifi-100 font-medium text-base">
                      {isDragActive
                        ? 'Drop your resume file here now...'
                        : 'Drag & drop your resume or click to browse'}
                    </p>
                    <p className="text-scifi-200 text-xs font-mono mt-2">
                      Supports PDF or DOCX formats (Up to 10MB)
                    </p>
                  </div>
                </div>
              )}
            </div>
          </div>

          {/* Job Description Text Area */}
          <div className="glass-card p-6 sm:p-8 rounded-3xl border border-scifi-600/30 shadow-2xl relative">
            <h2 className="text-xl font-heading font-bold mb-4 flex items-center text-scifi-100">
              <FileText className="w-5 h-5 mr-3 text-scifi-200" />
              2. Target Job Description
            </h2>

            <div className="relative">
              <textarea
                value={jobDescription}
                onChange={(e) => setJobDescription(e.target.value)}
                placeholder="Paste the target job description here (e.g. Senior Full Stack Engineer requiring React, Node.js, Docker, PostgreSQL)..."
                className="w-full h-48 glass-input rounded-2xl p-4 text-scifi-100 placeholder-scifi-200/50 focus:outline-none resize-none font-sans text-sm leading-relaxed"
              />

              <div className="flex items-center justify-between text-xs font-mono text-scifi-200 mt-2 px-1">
                <span>Auto-Keyword Visualizer Active</span>
                <span className="text-scifi-200">{jobDescription.length} characters</span>
              </div>
            </div>
          </div>

        </div>

        {/* Big Glow Analyze Action Button */}
        <div className="mt-10 text-center">
          <button
            onClick={handleAnalyze}
            disabled={!file || !jobDescription.trim()}
            className="group relative inline-flex items-center justify-center px-10 py-5 rounded-2xl font-heading font-extrabold text-lg text-scifi-100 bg-gradient-to-r from-scifi-700 via-scifi-600 to-scifi-800 disabled:opacity-40 disabled:cursor-not-allowed transition-all duration-300 hover:scale-[1.03] shadow-purple-glow overflow-hidden"
          >
            <Zap className="w-6 h-6 mr-3 text-scifi-200 group-hover:animate-bounce" />
            <span>Analyze Resume & Verify Profile</span>
            <ArrowRight className="w-5 h-5 ml-3 group-hover:translate-x-1 transition-transform" />
          </button>

          {/* Quick Dataset Explorer Trigger Button */}
          <div className="mt-6">
            <button
              onClick={() => setShowExplorer(!showExplorer)}
              className="inline-flex items-center space-x-2 text-xs font-mono text-scifi-200 hover:text-scifi-100 underline underline-offset-4 transition-colors"
            >
              <Cpu className="w-4 h-4" />
              <span>{showExplorer ? 'Hide Shared Mock Dataset Explorer' : 'Explore 20 Shared Developer Mock Profiles & SkillSwap Pairs'}</span>
            </button>
          </div>
        </div>

        {/* Shared Mock Profiles Explorer Component */}
        {showExplorer && (
          <SharedProfilesExplorer onSelectProfile={handleSelectMockProfile} />
        )}

      </div>

      {/* AI Platform Capabilities Section */}
      <div className="max-w-6xl mx-auto px-4 pb-20 relative z-10">
        <div className="text-center mb-10">
          <h2 className="text-2xl sm:text-3xl font-heading font-bold text-scifi-100 mb-2">
            SkillBridge AI Platform Modules
          </h2>
          <p className="text-scifi-200 text-sm font-mono">
            Autonomous verification and intelligence capabilities
          </p>
        </div>

        <div className="grid sm:grid-cols-2 lg:grid-cols-4 gap-6">

          <div className="glass-card-hover p-6 rounded-2xl text-center">
            <div className="w-12 h-12 rounded-xl bg-scifi-600/20 border border-scifi-600/40 flex items-center justify-center mx-auto mb-4 text-scifi-200">
              <CheckCircle2 className="w-6 h-6" />
            </div>
            <h3 className="font-heading font-bold text-base text-scifi-100 mb-2">ATS Verification</h3>
            <p className="text-scifi-200 text-xs leading-relaxed font-sans">
              Evaluates resume formatting, section detection, and keyword match percentages.
            </p>
          </div>

          <div className="glass-card-hover p-6 rounded-2xl text-center">
            <div className="w-12 h-12 rounded-xl bg-scifi-600/20 border border-scifi-600/40 flex items-center justify-center mx-auto mb-4 text-scifi-200">
              <Target className="w-6 h-6" />
            </div>
            <h3 className="font-heading font-bold text-base text-scifi-100 mb-2">Skill Verification</h3>
            <p className="text-scifi-200 text-xs leading-relaxed font-sans">
              Cross-checks claimed resume skills against real GitHub repositories and code commits.
            </p>
          </div>

          <div className="glass-card-hover p-6 rounded-2xl text-center">
            <div className="w-12 h-12 rounded-xl bg-scifi-600/20 border border-scifi-600/40 flex items-center justify-center mx-auto mb-4 text-scifi-200">
              <BookOpen className="w-6 h-6" />
            </div>
            <h3 className="font-heading font-bold text-base text-scifi-100 mb-2">Gap Roadmap</h3>
            <p className="text-scifi-200 text-xs leading-relaxed font-sans">
              Generates customized learning milestones and curated resources for missing skills.
            </p>
          </div>

          <div className="glass-card-hover p-6 rounded-2xl text-center">
            <div className="w-12 h-12 rounded-xl bg-scifi-600/20 border border-scifi-600/40 flex items-center justify-center mx-auto mb-4 text-scifi-200">
              <Mail className="w-6 h-6" />
            </div>
            <h3 className="font-heading font-bold text-base text-scifi-100 mb-2">Cover Letter AI</h3>
            <p className="text-scifi-200 text-xs leading-relaxed font-sans">
              Generates tailored, high-converting cover letters matching target job descriptions.
            </p>
          </div>

        </div>
      </div>
    </div>
  );
};

export default Home;
